text:
            data["Credit_History"]
        ),

        "Property_Area": data["Property_Area"],
    }


    # Create features
    features = create_features(input_data)


    # Prediction
    prediction = int(
        model.predict(features)[0]
    )


    # Probability
    probability = float(
        model.predict_proba(features)[0][1]
    )


    # Final result
    if prediction == 1:
        status = "Approved"
    else:
        status = "Rejected"


    return {

        "prediction": status,

        "approval_probability": round(
            probability * 100,
            2
        )
    }


